package local.skyfamily;
import android.app.TimePickerDialog;import android.content.*;import android.graphics.Bitmap;import android.net.Uri;import android.os.Handler;import android.view.*;import android.widget.*;import com.google.zxing.*;import com.google.zxing.common.BitMatrix;import java.util.*;
final class DashboardExtras {
 static final String STORE="https://play.google.com/store/apps/details?id=com.bubblecast";final PersonalActivity host;final Handler main=new Handler();boolean running=false;Boolean applied;TextView greeting,message,date;final Runnable minute=this::tick;
 DashboardExtras(PersonalActivity activity){host=activity;}
 static int setting(android.content.SharedPreferences preferences,String key,int fallback){if(preferences==null)return fallback;int value=preferences.getInt(key,fallback);return value>=0&&value<1440?value:fallback;}
 static boolean dark(android.content.SharedPreferences preferences){if(preferences==null)return false;if(!preferences.getBoolean("appearance.auto",false))return preferences.getString("appearance.manual","light").equals("dark");Calendar now=Calendar.getInstance();int time=now.get(Calendar.HOUR_OF_DAY)*60+now.get(Calendar.MINUTE),light=setting(preferences,"appearance.light",420),dark=setting(preferences,"appearance.dark",1140);if(light==dark)return preferences.getString("appearance.manual","light").equals("dark");boolean day=light<dark?time>=light&&time<dark:time>=light||time<dark;return !day;}
 void start(){running=true;applied=null;tick();}
 void stop(){running=false;main.removeCallbacks(minute);}
 void close(){stop();leavePage();}
 void leavePage(){greeting=message=date=null;}
 void tick(){boolean dark=dark(host.prefs);if(applied==null||applied.booleanValue()!=dark){applied=dark;host.applyAppearance();}Calendar now=Calendar.getInstance();int hour=now.get(Calendar.HOUR_OF_DAY);if(greeting!=null){greeting.setText(hour<12&&hour>=5?"Good morning":hour>=12&&hour<18?"Good afternoon":"Good evening");message.setText(hour<5?"A little quiet time, just for you.":hour<12?"A fresh start for your day.":hour<18?"Hope your day is going well.":"Settle in and enjoy your evening.");}if(date!=null)date.setText(new java.text.SimpleDateFormat("EEEE, d MMMM",Locale.getDefault()).format(now.getTime()));main.removeCallbacks(minute);if(running)main.postDelayed(minute,60000-System.currentTimeMillis()%60000);}
 void decorateHome(){TextClock clock=null;int index=-1;for(int i=0;i<host.body.getChildCount();i++)if(host.body.getChildAt(i) instanceof TextClock){clock=(TextClock)host.body.getChildAt(i);index=i;break;}if(clock!=null){if(index+1<host.body.getChildCount()&&host.body.getChildAt(index+1) instanceof TextView)date=(TextView)host.body.getChildAt(index+1);host.body.removeView(clock);LinearLayout row=new LinearLayout(host);row.setGravity(Gravity.CENTER_VERTICAL);row.setOrientation(LinearLayout.VERTICAL);row.addView(clock,new LinearLayout.LayoutParams(-1,-2));LinearLayout words=new LinearLayout(host);words.setOrientation(1);words.setPadding(host.dp(12),0,0,0);greeting=host.paperText("",26,PaperActivity.INK);message=host.paperText("",16,PaperActivity.MUTE);words.addView(greeting);words.addView(message);row.addView(words,new LinearLayout.LayoutParams(-1,-2));host.body.addView(row,index);row.addOnLayoutChangeListener((view,l,t,r,b,ol,ot,or,ob)->{boolean wide=r-l>=host.dp(540);int orientation=wide?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL;if(row.getOrientation()==orientation)return;row.setOrientation(orientation);View clockView=row.getChildAt(0),wordsView=row.getChildAt(1);clockView.setLayoutParams(new LinearLayout.LayoutParams(wide?0:-1,-2,wide?1:0));wordsView.setLayoutParams(new LinearLayout.LayoutParams(wide?0:-1,-2,wide?1.2f:0));});}host.body.addView(castCard(),Math.min(4,host.body.getChildCount()));tick();}
 LinearLayout castCard(){LinearLayout card=host.paperPanel("Cast from your phone");String name=host.prefs.getString("dlna.name","legacydash");card.addView(host.paperText("1. Connect phone and frame to the same local network.\n2. Enable this frame's DLNA receiver in Cast setup.\n3. In your sender, select the DLNA receiver: "+name+". Do not choose a Chromecast target.",16,PaperActivity.INK));card.addView(host.paperText("Scan to open the BubbleCast Play Store listing on your phone. Music support depends on the sender.",14,PaperActivity.MUTE));ImageView qr=new ImageView(host);qr.setScaleType(ImageView.ScaleType.FIT_CENTER);qr.setContentDescription("QR code for the BubbleCast Play Store listing, not a pairing code");card.addView(qr,new LinearLayout.LayoutParams(-1,host.dp(176)));final int stamp=host.revision;host.work(()->{Map<EncodeHintType,Object> hints=new EnumMap<>(EncodeHintType.class);hints.put(EncodeHintType.MARGIN,4);hints.put(EncodeHintType.CHARACTER_SET,"UTF-8");int size=Math.min(768,Math.max(256,host.dp(176)));BitMatrix bits=new MultiFormatWriter().encode(STORE,BarcodeFormat.QR_CODE,size,size,hints);int[] pixels=new int[size*size];for(int y=0;y<size;y++)for(int x=0;x<size;x++)pixels[y*size+x]=bits.get(x,y)?0xff000000:0xffffffff;Bitmap bitmap=Bitmap.createBitmap(pixels,size,size,Bitmap.Config.ARGB_8888);host.ui.post(()->{if(stamp==host.revision)qr.setImageBitmap(bitmap);else bitmap.recycle();});});TextView setup=host.paperText("Open receiver setup >",17,PaperActivity.INK);setup.setMinHeight(host.dp(48));setup.setFocusable(true);setup.setOnClickListener(view->host.castSetup());card.addView(setup);TextView link=host.paperText("Open BubbleCast listing >",17,PaperActivity.INK);link.setMinHeight(host.dp(48));link.setFocusable(true);link.setOnClickListener(view->{try{host.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(STORE)));}catch(Exception error){host.toast("No app available to open this link");}});card.addView(link);return card;}
 String time(int value){return String.format(Locale.US,"%02d:%02d",value/60,value%60);}
 boolean save(android.content.SharedPreferences.Editor editor){boolean ok=editor.commit();if(!ok)host.toast("Appearance NOT SAVED / check device storage");applied=null;tick();return ok;}
 void settings(){host.section("Light / dark schedule");host.text("Uses the device's local time. Theme changes affect native UI colours, not photo/video/artwork pixels.");CheckBox automatic=new CheckBox(host);automatic.setText("Automatic light / dark mode");automatic.setChecked(host.prefs.getBoolean("appearance.auto",false));host.body.addView(automatic);automatic.setOnCheckedChangeListener((button,value)->save(host.prefs.edit().putBoolean("appearance.auto",value)));host.button("Light now / disable automatic mode",()->{save(host.prefs.edit().putString("appearance.manual","light").putBoolean("appearance.auto",false));automatic.setChecked(false);});host.button("Dark now / disable automatic mode",()->{save(host.prefs.edit().putString("appearance.manual","dark").putBoolean("appearance.auto",false));automatic.setChecked(false);});timeControl("Light at","appearance.light",420,"appearance.dark",1140);timeControl("Dark at","appearance.dark",1140,"appearance.light",420);}
 void timeControl(String label,String key,int fallback,String other,int otherFallback){TextView control=host.paperText(label+" / "+time(setting(host.prefs,key,fallback)),18,PaperActivity.INK);control.setMinHeight(host.dp(52));control.setBackground(host.controlBackground());control.setFocusable(true);host.body.addView(control);control.setOnClickListener(view->{int current=setting(host.prefs,key,fallback);new TimePickerDialog(host,(picker,hour,minute)->{int value=hour*60+minute;if(value==setting(host.prefs,other,otherFallback)){host.toast("Choose different light and dark times");return;}if(save(host.prefs.edit().putInt(key,value)))control.setText(label+" / "+time(value));},current/60,current%60,true).show();});}
}
